'use strict';
const $=s=>document.querySelector(s), key='pocket-budget-v1';
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, cents=n=>Math.round(Number(n)*100), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), date=s=>new Date(s+'T12:00:00'), days=s=>Math.round((date(s)-date(today()))/86400000), pretty=s=>date(s).toLocaleDateString('en-US',{month:'short',day:'numeric'});
let state={ready:false,opening:0,saved:0,goal:'',target:0,payAmount:0,payDate:'',payFrequency:'weekly',transactions:[],costs:[]}, mode='', storageOkay=true;
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed.transactions)||!Array.isArray(parsed.costs))throw Error();state={...state,...parsed};}}catch{storageOkay=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));return true;}catch{storageOkay=false;return false;}}
function notify(message){$('#notice').textContent=message;}
function total(){return state.opening+state.transactions.reduce((a,t)=>a+(t.type==='in'?t.amount:t.type==='out'?-t.amount:0),0)}
function owed(){return state.costs.reduce((a,c)=>a+c.amount,0)}
function available(){return total()-state.saved-owed()}
function advance(s,f){let d=date(s);if(f==='monthly'){let day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));}else d.setDate(d.getDate()+(f==='weekly'?7:14));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function record(type,amount,title,when=today(),extra={}){state.transactions.push({id:uid(),type,amount,title,date:when,...extra})}
function finish(message){const ok=persist();render();$('#modal').close();notify(ok?message:message+' Browser storage is unavailable; keep this page open or your changes will be lost.');}
function activity(t){const sign=t.type==='in'?'+':t.type==='out'?'−':t.type==='save'?'↗':'↙';return `<div class="row"><span class="row-icon">${sign}</span><div class="row-info"><b>${esc(t.title)}</b><small>${pretty(t.date)} · ${{in:'Money in',out:'Money out',save:'Moved into savings',unsave:'Moved out of savings'}[t.type]}</small></div><span class="row-amount ${t.type==='in'?'positive':''}">${sign} ${money(t.amount)}</span></div>`}
function costRow(c,actions=false){let d=days(c.date),label=d<0?`${-d} day${d===-1?'':'s'} overdue`:d===0?'Due today':d===1?'Due tomorrow':pretty(c.date);return `<div class="row"><span class="row-icon">${c.frequency==='once'?'◷':'↻'}</span><div class="row-info"><b>${esc(c.title)}</b><small>${esc(c.kind)} · ${c.frequency==='once'?'One time':c.frequency}</small></div><span class="row-amount">${money(c.amount)}<small>${label}</small></span>${actions?`<div class="cost-actions"><button class="secondary" data-pay="${c.id}">Mark paid</button><button class="text-button" data-remove="${c.id}">Remove</button></div>`:''}</div>`}
function render(){
$('#today').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#total').textContent=money(total());$('#available').textContent=money(available());$('#reserved').textContent=money(state.saved);$('#balance-note').textContent=`After ${money(state.saved)} savings + ${money(owed())} unpaid costs.`;
let start=date(today());start.setDate(start.getDate()-((start.getDay()+6)%7));let week=state.transactions.filter(t=>date(t.date)>=start&&t.date<=today());$('#income').textContent=money(week.filter(t=>t.type==='in').reduce((a,t)=>a+t.amount,0));$('#spent').textContent=money(week.filter(t=>t.type==='out').reduce((a,t)=>a+t.amount,0));
$('#payday').textContent=state.payDate?(days(state.payDate)<0?'Check in':days(state.payDate)===0?'Today':`In ${days(state.payDate)} days`):'Not set';$('#pay-caption').textContent=state.payDate?`${money(state.payAmount)} expected · ${pretty(state.payDate)}`:'Add your allowance in setup';$('#received').hidden=!state.payDate;
$('#goal-name').textContent=state.goal||'Something worth saving for';$('#saved').textContent=money(state.saved);$('#target').textContent=`of ${money(state.target)}`;let pct=state.target?Math.min(100,Math.round(state.saved/state.target*100)):0;$('#percent').textContent=pct+'%';$('#progress').value=pct;$('#goal-message').textContent=!state.target?'Set a goal, then start putting money aside.':state.saved>=state.target?'You did it. Your goal is fully saved!':`${money(state.target-state.saved)} to go. You’ve got this.`;
let costs=[...state.costs].sort((a,b)=>a.date.localeCompare(b.date));$('#upcoming-short').innerHTML=costs.slice(0,3).map(c=>costRow(c)).join('')||'<p class="empty">Nothing coming up yet. Add subscriptions, school costs, or money you owe.</p>';$('#cost-list').innerHTML=costs.map(c=>costRow(c,true)).join('')||'<p class="empty">You’re all caught up. No unpaid costs.</p>';
let tx=[...state.transactions].reverse().sort((a,b)=>b.date.localeCompare(a.date));$('#recent').innerHTML=tx.slice(0,3).map(activity).join('')||'<p class="empty">A fresh start. Log some money to see your activity here.</p>';let f=$('#filter').value;$('#history-list').innerHTML=tx.filter(t=>f==='all'||(f==='save'?['save','unsave'].includes(t.type):t.type===f)).map(activity).join('')||'<p class="empty">No activity here yet.</p>';$('#paid-list').innerHTML=tx.filter(t=>t.costId).map(activity).join('')||'<p class="empty">Costs you mark paid will appear here.</p>';
let chart=[];for(let i=6;i>=0;i--){let d=date(today());d.setDate(d.getDate()-i);let dt=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let ts=state.transactions.filter(t=>t.date===dt);chart.push({label:d.toLocaleDateString('en-US',{weekday:'short'}),out:ts.filter(t=>t.type==='out').reduce((a,t)=>a+t.amount,0),saved:ts.filter(t=>t.type==='save').reduce((a,t)=>a+t.amount,0)});}let max=Math.max(100,...chart.flatMap(c=>[c.out,c.saved]));$('#chart').innerHTML=chart.map(c=>`<div class="day" title="${c.label}: spent ${money(c.out)}, saved ${money(c.saved)}"><div class="bars"><div class="bar" style="height:${c.out/max*100}%"></div><div class="bar saving" style="height:${c.saved/max*100}%"></div></div><span class="day-label">${c.label}</span></div>`).join('');
}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const amount=(label,name,value='',required=true)=>field(label,name,'number',value,`min="${required?'0.01':'0'}" max="1000000" step="0.01" ${required?'required':''}`);
function openModal(kind){mode=kind;$('#error').textContent='';$('#close').hidden=!state.ready;$('#modal-kicker').textContent=kind==='setup'?'YOUR MONEY STARTS HERE':'ONE SMALL STEP';let title='',desc='',html='',submit='Save';
if(kind==='setup'){title=state.ready?'Your money setup':'Hey, welcome to Pocket.';desc='A quick check-in to make this yours. Use your real amounts. Everything stays in this browser.';html=amount(state.ready?'Current total money ($), including savings':'How much money do you have now? ($)','opening',state.ready?total()/100:'',false)+'<div class="form-grid">'+amount('Next allowance ($)','payAmount',state.payAmount/100,false)+field('When will it arrive?','payDate','date',state.payDate)+'</div><label>How often?<select name="payFrequency"><option value="weekly">Every week</option><option value="fortnightly">Every 2 weeks</option><option value="monthly">Every month</option><option value="once">Just once</option></select></label>';if(!state.ready)html+=field('What are you saving for? (optional)','goal','text','','maxlength="70"')+'<div class="form-grid">'+amount('Goal price ($)','target','',false)+amount('Already set aside ($)','saved',0,false)+'</div>';submit=state.ready?'Update setup':'Let’s see my money →';}
if(kind==='transaction'){title='Log a little. Know a lot.';desc='Add one purchase or a whole week’s total. Record only money that has actually moved.';html='<label>What happened?<select name="type"><option value="out">I spent money</option><option value="in">I received money</option></select></label>'+amount('How much? ($)','amount')+field('What was it for?','title','text','','required maxlength="80" placeholder="Snacks this week, allowance…"')+field('When?','date','date',today(),`required max="${today()}"`);submit='Log money';}
if(kind==='cost'){title='Let’s plan for it.';desc='Add a subscription, a cost coming up, or money you owe.';html=field('What’s the cost?','title','text','','required maxlength="80" placeholder="Game pass, class trip…"')+'<div class="form-grid">'+amount('Amount ($)','amount')+field('Due date','date','date',today(),'required')+'</div><label>Type<select name="kind"><option>Upcoming cost</option><option>Subscription</option><option>Money I owe</option></select></label><label>Repeats<select name="frequency"><option value="once">Doesn’t repeat</option><option value="weekly">Weekly</option><option value="fortnightly">Every 2 weeks</option><option value="monthly">Monthly</option></select></label>';submit='Add cost';}
if(kind==='goal'){title='Something to look forward to.';desc='Pick a goal that means something to you.';html=field('Goal name','goal','text',state.goal,'required maxlength="70"')+amount('Target amount ($)','target',state.target?state.target/100:'');submit='Save goal';}
if(kind==='save'||kind==='unsave'){title=kind==='save'?'Give your goal a little boost.':'Move money out of savings';desc=kind==='save'?`${money(Math.max(0,available()))} available after unpaid costs. This moves your existing money, without changing your total.`:`${money(state.saved)} saved. Moving it back makes it available to spend.`;html=amount('How much? ($)','amount');submit=kind==='save'?'Add to savings':'Move back';}
$('#modal-title').textContent=title;$('#modal-desc').textContent=desc;$('#fields').innerHTML=html;$('#submit').textContent=submit;if(kind==='setup')$('[name="payFrequency"]').value=state.payFrequency;$('#modal').showModal();}
$('#form').addEventListener('submit',e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));const fail=m=>{$('#error').textContent=m;};let a=cents(d.amount||0);
if(mode==='setup'){let opening=cents(d.opening||0),saved=state.ready?state.saved:cents(d.saved||0),target=cents(d.target||0);if(saved>opening)return fail('Savings must be part of the money you already have.');if(!state.ready&&saved>0&&(!d.goal||!target))return fail('Add a goal name and price for your saved money.');if(!state.ready&&d.goal&&!target)return fail('Add a price for your goal.');if((cents(d.payAmount||0)>0)!==Boolean(d.payDate))return fail('Enter both the allowance amount and its date, or leave both empty.');if(state.ready){let delta=opening-total();if(delta)record(delta>0?'in':'out',Math.abs(delta),'Balance check-in');}else{state.opening=opening;state.saved=saved;state.goal=d.goal;state.target=target;}Object.assign(state,{ready:true,payAmount:cents(d.payAmount||0),payDate:d.payDate,payFrequency:d.payFrequency});finish('Your money picture is up to date.');}
else if(mode==='transaction'){if(d.date>today())return fail('Use today or an earlier date. Add future payments under Upcoming.');if(d.type==='out'&&a>total()-state.saved)return fail('That is more than your money outside savings. Move savings back first, or check your balance.');record(d.type,a,d.title.trim(),d.date);finish('Logged. Your totals are updated.');}
else if(mode==='cost'){state.costs.push({...d,amount:a,title:d.title.trim(),id:uid()});finish('Cost added. Your available money now accounts for it.');}
else if(mode==='goal'){state.goal=d.goal.trim();state.target=cents(d.target);finish('Your goal is ready.');}
else if(mode==='save'||mode==='unsave'){if(mode==='save'&&a>Math.max(0,available()))return fail('Choose an amount within your available money.');if(mode==='unsave'&&a>state.saved)return fail('You can’t move more than you have saved.');state.saved+=mode==='save'?a:-a;record(mode,a,mode==='save'?`Saved for ${state.goal||'my goal'}`:'Moved savings back');finish(mode==='save'?'A little closer to your goal!':'Money moved back to spending.');}});
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==v.dataset.view);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v.dataset.view));}const p=e.target.closest('[data-pay]');if(p){const c=state.costs.find(x=>x.id===p.dataset.pay);if(!c)return;if(c.amount>total()-state.saved){notify('Not enough money outside savings. Update your money or move savings back first.');return;}if(!confirm(`Record ${money(c.amount)} paid for ${c.title}?`))return;record('out',c.amount,c.title,today(),{costId:c.id});if(c.frequency==='once')state.costs=state.costs.filter(x=>x.id!==c.id);else c.date=advance(c.date,c.frequency);finish('Payment logged. '+(c.frequency!=='once'?'The next charge is now listed.':''));}const r=e.target.closest('[data-remove]');if(r&&confirm('Remove this planned cost? This does not record a payment.')){state.costs=state.costs.filter(c=>c.id!==r.dataset.remove);finish('Planned cost removed.');}});
$('#add').onclick=$('#weekly').onclick=()=>openModal('transaction');$('#settings').onclick=()=>openModal('setup');$('#add-cost').onclick=$('#new-cost').onclick=()=>openModal('cost');$('#edit-goal').onclick=()=>openModal('goal');$('#save-money').onclick=()=>openModal(state.target?'save':'goal');$('#take-money').onclick=()=>openModal('unsave');$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('cancel',e=>{if(!state.ready)e.preventDefault();});$('#filter').onchange=render;$('#received').onclick=()=>{if(!confirm(`Have you actually received ${money(state.payAmount)}?`))return;record('in',state.payAmount,'Allowance received');if(state.payFrequency==='once')state.payDate='';else state.payDate=advance(state.payDate,state.payFrequency);finish('Allowance logged. Your next money day is updated.');};render();if(!storageOkay)notify('Saved data could not be loaded. Browser storage may be unavailable.');if(!state.ready)openModal('setup');
